def diagonal_bound_table(kmax: int = 12) -> None:
    print(f"{'k':>3} {'C(2k,k)':>10} {'4^k':>12} {'ratio':>10}")
    for k in range(kmax + 1):
        cb = comb(2 * k, k)
        fp = 4 ** k
        print(f"{k:>3} {cb:>10} {fp:>12} {cb / fp:>10.4f}")
        assert cb <= fp

if __name__ == '__main__':
    diagonal_bound_table()

