function HAS_MONO_CLIQUE(V, redAdj, s, red):
    for each subset T of V with |T| = s:
        monochromatic <- true
        for each unordered pair {a,b} in T:
            e <- redAdj(a,b)
            if red and not e: monochromatic <- false; break
            if (not red) and e: monochromatic <- false; break
        if monochromatic: return true
    return false

