function ES_THRESHOLD(s, t):   # returns upper bound for R(s,t)
    create table B[1..s][1..t]
    for i in 1..s: B[i][1] <- 1
    for j in 1..t: B[1][j] <- 1
    for i in 2..s:
        for j in 2..t:
            B[i][j] <- B[i-1][j] + B[i][j-1]
    return B[s][t]            # equals C(s+t-2, s-1)

